import{_ as e,o as a,c as d,a5 as n}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"模型、服务、API 与客户端","description":"用一张调用链讲清模型、服务商、API、令牌、客户端和 Agent 的区别。","frontmatter":{"title":"模型、服务、API 与客户端","description":"用一张调用链讲清模型、服务商、API、令牌、客户端和 Agent 的区别。"},"headers":[],"relativePath":"concepts/model-api-client.md","filePath":"concepts/model-api-client.md","lastUpdated":1788838685000}'),s={name:"concepts/model-api-client.md"};function o(i,t,l,p,c,r){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="模型、服务、api-与客户端" tabindex="-1">模型、服务、API 与客户端 <a class="header-anchor" href="#模型、服务、api-与客户端" aria-label="Permalink to &quot;模型、服务、API 与客户端&quot;">​</a></h1><p>新手最常见的混乱，是把模型名、网站、接口和软件混为一谈。记住一条调用链就够了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你 → 客户端 → API 地址 + 令牌 → 服务商 → 模型 → 返回结果</span></span></code></pre></div><h2 id="_1-六个角色分别做什么" tabindex="-1">1. 六个角色分别做什么 <a class="header-anchor" href="#_1-六个角色分别做什么" aria-label="Permalink to &quot;1. 六个角色分别做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>通俗理解</th><th>例子</th><th>决定什么</th></tr></thead><tbody><tr><td>模型</td><td>发动机</td><td>GPT、Claude、Gemini、Qwen</td><td>能力上限、速度、输入输出类型</td></tr><tr><td>服务商</td><td>提供发动机的人</td><td>OpenAI、Anthropic、Google 或接口平台</td><td>可用模型、额度、稳定性和计费</td></tr><tr><td>API</td><td>统一的调用入口</td><td>HTTP 请求与 JSON 响应</td><td>软件如何连接服务</td></tr><tr><td>API 地址</td><td>服务入口位置</td><td><code>https://api.example.com/v1</code></td><td>请求发到哪里</td></tr><tr><td>令牌</td><td>账户钥匙</td><td><code>sk-xxxxxxxx</code></td><td>谁在调用、扣谁的额度</td></tr><tr><td>客户端</td><td>你操作的软件</td><td>Claude Code、Codex、Cursor</td><td>工作方式、能否读文件和执行命令</td></tr></tbody></table><p>同一个客户端可以连接不同服务，同一个服务可以提供多个模型，同一个模型也可能由不同客户端调用。所以“软件不好用”需要继续拆成：是客户端体验、接口连接，还是模型能力的问题。</p><h2 id="_2-agent-又多做了什么" tabindex="-1">2. Agent 又多做了什么 <a class="header-anchor" href="#_2-agent-又多做了什么" aria-label="Permalink to &quot;2. Agent 又多做了什么&quot;">​</a></h2><p>普通聊天通常只有“输入文字 → 返回文字”。Agent 会循环执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解目标 → 制定步骤 → 调用工具 → 观察结果 → 调整计划 → 交付</span></span></code></pre></div><p>工具可以是读取文件、搜索代码、运行测试、访问数据库或操作浏览器。Agent 的价值不是“更会聊天”，而是能把多个动作串成任务；风险也来自这里，因此要设置权限、审查命令并保留回滚点。</p><h2 id="_3-一次请求里发生了什么" tabindex="-1">3. 一次请求里发生了什么 <a class="header-anchor" href="#_3-一次请求里发生了什么" aria-label="Permalink to &quot;3. 一次请求里发生了什么&quot;">​</a></h2><ol><li>客户端把系统规则、聊天历史、你的任务和相关文件整理成上下文。</li><li>客户端携带令牌，把请求发送到 API 地址。</li><li>服务商验证令牌、额度和模型权限。</li><li>模型根据上下文生成结果，Agent 可能继续调用工具。</li><li>服务商按输入与输出 Token、请求次数或套餐规则计费。</li></ol><p>这解释了三个现象：历史越长通常越贵；换客户端不一定会换模型；模型正常但地址或令牌错误时仍然无法使用。</p><h2 id="_4-配置时必须确认的五项" tabindex="-1">4. 配置时必须确认的五项 <a class="header-anchor" href="#_4-配置时必须确认的五项" aria-label="Permalink to &quot;4. 配置时必须确认的五项&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API 地址：是否包含文档要求的路径，例如 /v1</span></span>
<span class="line"><span>令牌：是否复制完整、是否还有额度、是否放在正确字段</span></span>
<span class="line"><span>模型名：必须与服务商实际提供的名称完全一致</span></span>
<span class="line"><span>协议：客户端需要 OpenAI 兼容、Anthropic 兼容，还是原生协议</span></span>
<span class="line"><span>网络：域名能否访问，代理是否错误接管连接</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">不要泄露令牌</p><p>令牌不要放进截图、聊天记录、Git 仓库或前端代码。示例统一使用 <code>sk-xxxxxxxx</code>；一旦误传，立即到控制台撤销并创建新令牌。</p></div><h2 id="_5-出错时按层判断" tabindex="-1">5. 出错时按层判断 <a class="header-anchor" href="#_5-出错时按层判断" aria-label="Permalink to &quot;5. 出错时按层判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先检查</th></tr></thead><tbody><tr><td><code>command not found</code></td><td>客户端是否安装、PATH 是否生效</td></tr><tr><td><code>401</code> / <code>Unauthorized</code></td><td>令牌错误、过期或未被客户端读取</td></tr><tr><td><code>404</code> / <code>model not found</code></td><td>API 地址、模型名、协议兼容性</td></tr><tr><td><code>429</code> / <code>rate limit</code></td><td>额度、并发、服务容量、重试间隔</td></tr><tr><td>能回答但不会改文件</td><td>当前是聊天模式、目录未授权或工具权限未开启</td></tr><tr><td>修改结果不符合项目规范</td><td>上下文不足、规则文件缺失、验收标准不清</td></tr></tbody></table><p>需要完整流程时，转到《<a href="/ai-handbook/help/troubleshooting">通用排错手册</a>》。</p>`,19)])])}const b=e(s,[["render",o]]);export{u as __pageData,b as default};
